function art(f='green',key=''){let specific=key;if(key.includes('rose'))specific='rose';else if(key.includes('jasmine')||key==='neroli')specific='jasmine';else if(key.includes('tea')||key==='mate')specific='tea';else if(key.includes('musk'))specific='musk';else if(key.includes('iris')||key==='orris')specific='iris';return `<svg class="note-art ${esc(f)}" viewBox="0 0 64 66" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linejoin="round" stroke-linecap="round" aria-hidden="true">${MATERIAL_ART[specific]||BOTANICAL[f]||BOTANICAL.amber}</svg>`;}

const NAV=[['discover','الاستكشاف'],['library','خزانتي'],['notes','دليل النوتات'],['compare','المقارنة'],['journal','مذكرة العطر'],['profile','بصمتي العطرية']];
const GUEST_KEY='scentory-v2:guest';let storageAvailable=true;
function read(key){try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageAvailable=false;return false;}}
let state=cleanState(read(GUEST_KEY)||read('scentory-b-v1')),items=[],meta={},page='discover',activeList='favorite',limit=24,sort='curated';
let filters={query:'',brand:'',family:'',notes:[],exclude:[],images:false},filterOpen=false,noteQuery='',noteFamily='',noteLimit=60;
let user=null,cloudRevision=0,cloudReady=false,dirty=false,syncBusy=false,syncPaused=false,syncTimer,toastTimer,installPrompt=null,returnFocus=null,currentDetail=null;
let stateKey=GUEST_KEY;
const today=()=>new Date().toLocaleDateString('en-CA');
const dateText=d=>{try{return new Intl.DateTimeFormat('ar-AE',{day:'numeric',month:'long',year:'numeric'}).format(new Date(d+'T12:00:00'));}catch{return d;}};
const byId=id=>items.find(p=>p.id===id),isIn=(list,id)=>state.lists[list]?.includes(id);
function allItems(){items=[...(meta.items||[]),...state.custom];}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function save(){state.updatedAt=Date.now();const saved=write(stateKey,state);if(!saved)toast('مساحة الحفظ غير متاحة؛ صدّر نسخة احتياطية من الإعدادات.');dirty=true;if(user)write(stateKey+':dirty',true);clearTimeout(syncTimer);syncTimer=setTimeout(flushCloud,650);updateNav();updateTray();updateStatus();}
function updateStatus(){const txt=!navigator.onLine?'دون اتصال':syncPaused?'المزامنة بحاجة إلى مراجعة':syncBusy?'جارٍ الحفظ…':user&&cloudReady?(dirty?'بانتظار المزامنة':'محفوظ في حسابك'):storageAvailable?'محفوظ على هذا الجهاز':'الحفظ المحلي غير متاح';$('#connection').textContent=txt;$('#sync-label').textContent=txt;$('#account-label').textContent=user?.username||'مكتبتي الشخصية';}
async function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(15000),cache:'no-store'});let data;try{data=await r.json();}catch{throw new Error('خدمة الحساب غير متاحة الآن؛ مكتبتك المحلية محفوظة.');}if(!r.ok){const e=new Error(data.error||'تعذر الاتصال');e.status=r.status;e.data=data;throw e;}return data;}
async function flushCloud(){if(!user||!cloudReady||!dirty||syncBusy||syncPaused||!navigator.onLine)return;syncBusy=true;updateStatus();const snapshot=structuredClone(state),stamp=snapshot.updatedAt;
 try{const r=await api('state',{state:snapshot,baseRevision:cloudRevision});cloudRevision=r.revision;if(state.updatedAt===stamp){dirty=false;write(stateKey+':dirty',false);}write(stateKey+':revision',cloudRevision);}
 catch(e){if(e.status===409){syncPaused=true;toast('لديك تغييرات من جهاز آخر. افتح الحساب لدمج النسختين.');}else if(e.status===401){cloudReady=false;toast('انتهت جلسة الحساب. مكتبتك محفوظة على هذا الجهاز.');}else toast('تعذرت المزامنة؛ التغييرات محفوظة على الجهاز حتى عودة الاتصال.');}
 finally{syncBusy=false;updateStatus();if(dirty&&!syncPaused&&cloudReady&&state.updatedAt!==stamp)syncTimer=setTimeout(flushCloud,700);}}
async function connectUser(account,{importGuest=false}={}){const guest=cleanState(state);user=account;stateKey='scentory-v2:'+user.id;const local=read(stateKey);dirty=!!read(stateKey+':dirty');state=cleanState(local);cloudReady=false;syncPaused=false;
 try{const remote=await api('state');cloudRevision=remote.revision||0;if(dirty&&local){const previous=Number(read(stateKey+':revision')||0);if(previous!==cloudRevision){syncPaused=true;toast('وجدنا تغييرات على جهاز آخر. يمكنك دمجها من الحساب.');}}else{state=cleanState(remote.state);dirty=false;}cloudReady=true;if(importGuest){state=mergeStates(state,guest);dirty=true;}write(stateKey,state);write(stateKey+':revision',cloudRevision);}
 catch{toast('تعذر تحميل الحساب؛ نعرض نسختك المحفوظة على هذا الجهاز.');}
 allItems();render();updateStatus();if(dirty&&cloudReady)flushCloud();}
function image(p,cls='',eager=false){return p.image?`<img class="${cls}" src="${esc(p.image)}" alt="زجاجة ${esc(p.name)} من ${esc(p.brand)}" loading="${eager?'eager':'lazy'}" decoding="async" referrerpolicy="no-referrer" data-product-image="${esc(p.id)}">`:`<span class="no-photo" aria-label="صورة غير متوفرة">${esc(p.name[0]||'S')}<small>صورة غير متوفرة</small></span>`;}
function card(p,reason=''){const rating=state.personal[p.id]?.rating;return `<article class="perfume-card"><button class="card-heart ${isIn('favorite',p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${isIn('favorite',p.id)?'إزالة من':'إضافة إلى'} المفضلة: ${esc(p.name)}" aria-pressed="${isIn('favorite',p.id)}">${icon('heart',17)}</button><button class="card-compare ${state.compare.includes(p.id)?'active':''}" data-action="compare-add" data-id="${p.id}" aria-label="مقارنة ${esc(p.name)}" aria-pressed="${state.compare.includes(p.id)}">${icon('compare',16)}</button><button class="product-open" data-action="detail" data-id="${p.id}"><div class="product-image">${image(p)}</div><span class="card-brand" lang="en">${esc(p.brand)}</span><h3 class="card-title" lang="en">${esc(p.name)}</h3><p class="card-notes">${allNotes(p).slice(0,3).map(n=>esc(noteInfo(n).ar)).join(' · ')||'النوتات غير متوفرة بعد'}</p></button>${reason?`<p class="match-reason">${esc(reason)}</p>`:''}<div class="card-bottom">${rating?`${icon('star',12)} <span>تقييمي ${rating}/10</span>`:''}${isIn('owned',p.id)?`<span class="owned-badge">${icon('check',10)} في خزانتي</span>`:''}</div></article>`;}
function updateNav(){const markup=(mobile=false)=>(mobile?NAV.filter(x=>x[0]!=='compare'):NAV).map(([id,label])=>`<a href="#${id}" class="nav-item ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='library'?`<small>${new Set(Object.values(state.lists).flat()).size}</small>`:''}${id==='compare'&&state.compare.length?`<small>${state.compare.length}</small>`:''}</a>`).join('');$('#desktop-nav').innerHTML=markup();$('#mobile-nav').innerHTML=markup(true);$('#breadcrumb').innerHTML=`مساحتك الخاصة <span>/</span> ${NAV.find(x=>x[0]===page)?.[1]||'الاستكشاف'}`;}
function updateTray(){const tray=$('#compare-tray');tray.hidden=!state.compare.length||page==='compare';if(tray.hidden)return;tray.innerHTML=`<div class="tray-photos">${state.compare.map(id=>{const p=byId(id);return p?`<div class="tray-item">${image(p)}<button data-action="compare-remove" data-id="${id}" aria-label="إزالة ${esc(p.name)} من المقارنة">×</button></div>`:'';}).join('')}</div><div class="tray-copy">مساحة المقارنة<small>${state.compare.length} من ٣ عطور</small></div><a class="primary-button" href="#compare">قارن الآن ${icon('arrow',15)}</a><button data-action="compare-clear" aria-label="إلغاء المقارنة">${icon('close',15)}</button>`;}
function intro(title,copy,eyebrow,action=''){return `<div class="page-intro"><span class="eyebrow">${eyebrow}</span><div class="intro-actions"><h1>${title}</h1>${action}</div><p>${copy}</p></div>`;}
function empty(title,copy,action='<a class="primary-button" href="#discover">استكشف العطور '+icon('arrow',16)+'</a>'){return `<div class="empty-state"><span class="empty-symbol">S</span><h3>${title}</h3><p>${copy}</p>${action}</div>`;}
function render(){allItems();updateNav();const views={discover:renderDiscover,library:renderLibrary,notes:renderNotes,compare:renderCompare,journal:renderJournal,profile:renderProfile};$('#content').innerHTML=(views[page]||renderDiscover)();updateTray();updateStatus();}
function renderDiscover(){const hero=['layton','naxos','reflection'].map(byId).filter(Boolean);return `<section class="hero"><div class="hero-copy"><span class="eyebrow">THE PRIVATE FRAGRANCE ATELIER</span><h1>عطرٌ يشبهك.<br>وحكاية <em>تبدأ بك.</em></h1><p>اكتشف ما يلامس ذوقك. احتفظ بما تحبّه، وتعرّف على النوتات، واكتب حكايتك مع كل عطر.</p><div class="hero-actions"><button class="primary-button" data-action="browse">اكتشف عطرك القادم ${icon('arrow',16)}</button><a class="text-button" href="#library">إلى خزانتي ${icon('library',15)}</a></div></div><div class="hero-art" aria-label="معرض زجاجات العطور الأصلية">${hero.map(p=>image(p,'hero-bottle',true)).join('')}<span class="edition">A collection, uniquely yours.</span></div></section><div class="catalog-stats"><span><b>${meta.stats?.fragrances||items.length}</b>عطرًا</span><span><b>${meta.stats?.brands||0}</b>دار عطور</span><span class="stat-note">صور أصلية<br>ونوتات من مصادرها</span></div><section class="collection-picks" aria-label="مسارات الاستكشاف">${[['green','نفسٌ أخضر','نعناع · شاي · لافندر'],['woody','أثرٌ من الخشب','أرز · صندل · فيتيفر'],['gourmand','دفءٌ هادئ','فانيلا · تونكا · عسل']].map(([f,title,sub])=>`<button class="collection-pick" data-action="preset" data-value="${f}">${art(f)}<span><h3>${title}</h3><small>${sub}</small></span>${icon('arrow',17)}</button>`).join('')}</section><section id="catalog-section"><div class="section-heading"><div><span class="eyebrow">THE FRAGRANCE INDEX</span><h2>عالمٌ من الروائح</h2><p>ابدأ باسم عطر، دار، أو نوتة تحبّها.</p></div><button class="secondary-button" data-action="add-custom">${icon('plus',14)} إضافة عطر</button></div><div class="catalog-controls"><div class="search-row"><label class="search-box" for="catalog-search">${icon('search',20)}<input id="catalog-search" type="search" value="${esc(filters.query)}" placeholder="ابحث بالعربية أو الإنجليزية…" autocomplete="off" spellcheck="false"><button type="button" class="icon-button" data-action="clear-query" aria-label="مسح البحث" ${filters.query?'':'hidden'}>${icon('close',15)}</button></label><button class="filter-button ${filterOpen?'active':''}" data-action="toggle-filters" aria-expanded="${filterOpen}" aria-controls="filters-panel">${icon('filter',18)} تصفية</button></div><div class="family-row" aria-label="العائلات العطرية">${[['','الكل'],...Object.entries(FAMILIES)].map(([f,label])=>`<button class="chip ${filters.family===f?'active':''}" data-action="family" data-value="${f}" aria-pressed="${filters.family===f}">${label}</button>`).join('')}</div><div id="filters-slot">${renderFilters()}</div><div id="catalog-results">${renderResults()}</div></div></section>`;}
function renderFilters(){const notes=noteIndex();return `<div id="filters-panel" class="filters-panel" ${filterOpen?'':'hidden'}><div class="field"><label for="brand-filter">دار العطور</label><select id="brand-filter"><option value="">جميع الدور</option>${[...new Set(items.map(p=>p.brand))].sort().map(b=>`<option ${filters.brand===b?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></div><div class="field"><label for="note-filter">يحتوي على النوتة</label><select id="note-filter"><option value="">اختر نوتة لإضافتها…</option>${notes.map(([key,n])=>`<option value="${esc(key)}">${esc(n.ar)} — ${esc(key)}</option>`).join('')}</select></div><div class="field"><label for="exclude-filter">استبعاد نوتة</label><select id="exclude-filter"><option value="">نوتة لا تفضّلها…</option>${notes.map(([key,n])=>`<option value="${esc(key)}">${esc(n.ar)} — ${esc(key)}</option>`).join('')}</select></div><div class="field"><label class="check-label"><input type="checkbox" id="official-filter" ${filters.images?'checked':''}> صور رسمية فقط</label><button class="text-button" data-action="reset-filters">مسح التصفية</button></div><div class="full active-notes">${filters.notes.map(n=>`<button class="chip active" data-action="remove-note" data-value="${esc(n)}">${esc(noteInfo(n).ar)} ${icon('close',12)}</button>`).join('')}${filters.exclude.map(n=>`<button class="chip" data-action="remove-exclude" data-value="${esc(n)}">بدون ${esc(noteInfo(n).ar)} ${icon('close',12)}</button>`).join('')}</div><small class="help-text full">التصفية حسب النوتات المعلنة؛ غياب نوتة من القائمة لا يضمن خلو التركيبة منها.</small></div>`;}
function sortedResults(){let results=filterCatalog(items,filters);if(sort==='name')results.sort((a,b)=>a.name.localeCompare(b.name));else if(sort==='brand')results.sort((a,b)=>a.brand.localeCompare(b.brand)||a.name.localeCompare(b.name));else if(sort==='rating')results.sort((a,b)=>(state.personal[b.id]?.rating||0)-(state.personal[a.id]?.rating||0));else{const featured=['naxos','layton','reflection','althair','erba-pura','imagination','aventus','br540','oud-wood'];results.sort((a,b)=>{const score=p=>(p.imageStatus==='official'?100:0)+(p.notesStatus==='official'?10:0)+(featured.includes(p.id)?1000-featured.indexOf(p.id):0);return score(b)-score(a);});}return results;}
function renderResults(){const results=sortedResults();return `<div class="results-meta"><span role="status" aria-live="polite">${results.length} عطرًا ${filters.query||filters.family||filters.brand||filters.notes.length?'يناسب بحثك':'في الكتالوج'}</span><label><span class="visually-hidden">ترتيب العطور</span><select class="sort-select" id="sort-select"><option value="curated" ${sort==='curated'?'selected':''}>الاختيارات أولًا</option><option value="name" ${sort==='name'?'selected':''}>حسب اسم العطر</option><option value="brand" ${sort==='brand'?'selected':''}>حسب دار العطور</option><option value="rating" ${sort==='rating'?'selected':''}>تقييمي الشخصي</option></select></label></div><div class="perfume-grid">${results.length?results.slice(0,limit).map(p=>card(p)).join(''):empty('لم نجد العطر بعد','جرّب كتابة اسم مختلف، أو أزل بعض النوتات من التصفية. ويمكنك إضافة عطر خاص بك.',`<button class="secondary-button" data-action="reset-filters">مسح البحث والتصفية</button> <button class="primary-button" data-action="add-custom">إضافة العطر</button>`)}</div>${results.length>limit?`<button class="secondary-button load-more" data-action="load-more">عرض المزيد <small>(${Math.min(limit,results.length)} من ${results.length})</small> ${icon('plus',15)}</button>`:''}`;}
function updateResults(){const target=$('#catalog-results');if(target)target.innerHTML=renderResults();const clear=$('[data-action="clear-query"]');if(clear)clear.hidden=!filters.query;}
function renderLibrary(){const ids=state.lists[activeList],result=ids.map(byId).filter(Boolean),unavailable=ids.length-result.length;return intro('خزانةٌ تحكي ذوقك.','كل ما تحبّه، تقتنيه، أو تتطلع إلى تجربته. في مكان واحد.','YOUR PERSONAL COLLECTION',`<button class="primary-button" data-action="add-custom">${icon('plus',15)} إضافة عطر</button>`)+`<div class="library-stats">${Object.entries(LISTS).map(([k,label])=>`<button class="mini-stat" data-action="list-tab" data-value="${k}"><strong>${state.lists[k].length}</strong><span>${label}</span></button>`).join('')}</div><div class="list-tabs">${Object.entries(LISTS).map(([k,label])=>`<button class="chip ${activeList===k?'active':''}" data-action="list-tab" data-value="${k}">${label} <small>${state.lists[k].length}</small></button>`).join('')}</div>${unavailable?`<p class="help-text">${unavailable} عطر محفوظ من الكتالوج السابق؛ سيظهر عند استعادة بياناته. لم تُحذف قوائمك.</p>`:''}<div class="perfume-grid">${result.length?result.map(p=>card(p)).join(''):empty('هنا تبدأ حكاية خزانَتك.','افتح أي عطر وأضفه إلى هذه القائمة، أو أضف عطرًا من مجموعتك.')}</div>`;}
function noteIndex(){const map=new Map();for(const p of items)for(const key of noteKeysOf(p)){if(!map.has(key))map.set(key,{...noteInfo(key),count:0});map.get(key).count++;}return [...map.entries()].sort((a,b)=>b[1].count-a[1].count);}
function renderNotes(){const index=noteIndex().filter(([key,n])=>(!noteFamily||n.family===noteFamily)&&(!noteQuery||norm(key+' '+n.ar).includes(norm(noteQuery))));return intro('تعرّف على لغة العطر.','خامات وروائح تكشف ما الذي يجذبك فعلًا. اختر أي نوتة لاستكشاف العطور التي تحتويها.','THE OLFACTORY LIBRARY')+`<label class="search-box" for="note-search">${icon('search')}<input id="note-search" type="search" placeholder="ابحث عن نوتة…" value="${esc(noteQuery)}"></label><div class="note-groups">${[['','الكل'],...Object.entries(FAMILIES)].map(([f,label])=>`<button class="chip ${noteFamily===f?'active':''}" data-action="note-family" data-value="${f}">${label}</button>`).join('')}</div><div class="results-meta"><span>${index.length} نوتة في الكتالوج</span><span>رسومات توضيحية · بلا قصّ للصور</span></div><div class="note-grid">${index.slice(0,noteLimit).map(([key,n])=>`<button class="note-tile" data-action="explore-note" data-value="${esc(key)}">${art(n.family,key)}<b>${esc(n.ar)}</b><small lang="en">${esc(key)}</small><em>${n.count} عطرًا</em></button>`).join('')||empty('لا توجد نوتات مطابقة','جرّب اسم النوتة بالإنجليزية أو أزل التصفية.','')}</div>${index.length>noteLimit?'<button class="secondary-button load-more" data-action="more-notes">المزيد من النوتات</button>':''}`;}
function renderCompare(){const ps=state.compare.map(byId).filter(Boolean);if(!ps.length)return intro('قارن، ثم قرّر.','حتى ثلاثة عطور جنبًا إلى جنب. النوتات، تقييمك، وما يميز كل اختيار.','A CLOSER LOOK')+empty('أيّ العطور أقرب إليك؟','استخدم رمز المقارنة في بطاقة أي عطر لإضافته هنا.');const rows=[['العائلات العطرية',p=>families(p).map(f=>`<span class="compare-note">${FAMILIES[f]}</span>`).join('')||'غير متوفرة'],['النوتات الافتتاحية',p=>renderCompareNotes(p.notes.top)],['نوتات القلب',p=>renderCompareNotes(p.notes.middle)],['نوتات القاعدة',p=>renderCompareNotes(p.notes.base)],['النوتات الرئيسية',p=>renderCompareNotes(p.notes.key)],['تقييمي',p=>state.personal[p.id]?.rating?`${state.personal[p.id].rating} / 10`:'لم أقيّمه بعد'],['ملاحظتي',p=>esc(state.personal[p.id]?.note||'لم أكتب ملاحظة بعد')],['في قوائمي',p=>Object.entries(LISTS).filter(([k])=>isIn(k,p.id)).map(([,l])=>l).join(' · ')||'لم أضفه بعد'],['توثيق النوتات',p=>p.notesStatus==='official'?'مذكورة في موقع الدار':p.notesStatus==='custom'?'إضافة شخصية':p.notesStatus==='legacy'?'من الكتالوج السابق · تحتاج مراجعة':'غير متوفرة']];return intro('الاختيار في التفاصيل.','مقارنة واضحة من المعلومات المتاحة، بلا تقييمات مجتمعية أو أرقام أداء غير موثقة.','A CLOSER LOOK',`<button class="secondary-button" data-action="compare-clear">مسح المقارنة</button>`)+`<div class="compare-scroll"><table class="compare-table"><caption class="visually-hidden">مقارنة العطور المختارة</caption><thead><tr>${ps.map(p=>`<th scope="col"><button class="text-button" data-action="compare-remove" data-id="${p.id}">${icon('close',12)} إزالة</button><button class="product-open" data-action="detail" data-id="${p.id}"><div class="product-image">${image(p)}</div><span class="card-brand">${esc(p.brand)}</span><h3>${esc(p.name)}</h3></button></th>`).join('')}${ps.length<3?`<th><a class="secondary-button" href="#discover">${icon('plus',16)} إضافة عطر</a></th>`:''}</tr></thead><tbody>${rows.map(([label,fn])=>`<tr>${ps.map(p=>`<td><span class="compare-label">${label}</span>${fn(p)}</td>`).join('')}${ps.length<3?'<td></td>':''}</tr>`).join('')}</tbody></table></div>`;}
const renderCompareNotes=ns=>ns?.length?ns.map(n=>`<span class="compare-note">${esc(noteInfo(n).ar)}</span>`).join(''):'—';
function renderJournal(){const entries=[...state.journal].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id));return intro('لكلّ يومٍ أثر.','وثّق العطر الذي ارتديته، شعورك به، وثباته على بشرتك. ذاكرتك أدق من الانطباع الأول.','THE SCENT JOURNAL',`<button class="primary-button" data-action="new-journal">${icon('plus',15)} تجربة جديدة</button>`)+`<div class="journal-list">${entries.length?entries.map(j=>{const p=byId(j.perfumeId);return `<article class="journal-entry"><button class="journal-image" data-action="detail" data-id="${j.perfumeId}" aria-label="تفاصيل ${esc(p?.name||'العطر')}">${p?image(p):icon('bottle',30)}</button><div class="journal-copy"><span class="card-brand">${esc(p?.brand||'عطر محفوظ')}</span><h3>${esc(p?.name||j.perfumeId)}</h3><div class="journal-meta"><span>${dateText(j.date)}</span>${j.occasion?`<span>${esc(j.occasion)}</span>`:''}${j.rating?`<span>تجربتي ${j.rating}/10</span>`:''}${j.longevity?`<span>الثبات ${j.longevity} ساعات</span>`:''}${j.sillage?`<span>الفوحان ${({close:'قريب',moderate:'متوسط',strong:'قوي'})[j.sillage]}</span>`:''}</div>${j.note?`<p>${esc(j.note)}</p>`:''}</div><button class="icon-button" data-action="delete-journal" data-id="${j.id}" aria-label="حذف هذه التجربة">${icon('trash',14)}</button></article>`;}).join(''):empty('أول تجربة تستحق أن تُكتب.','سجّل ما ترتديه اليوم، وراقب كيف تتطور علاقتك بالعطور مع الوقت.',`<button class="primary-button" data-action="new-journal">${icon('plus',15)} اكتب تجربتك الأولى</button>`)}</div>`;}
function renderProfile(){const profile=tasteProfile(items,state),count=new Set([...state.lists.owned,...state.lists.favorite]).size;if(!profile.length)return intro('ذوقك لا يشبه أحدًا.','بصمتك تتكوّن من عطورك المفضلة ومقتنياتك، وتكشف النوتات التي تتكرر في اختياراتك.','YOUR OLFACTORY SIGNATURE')+empty('لنكتشف بصمتك.','أضف بعض العطور إلى المفضلة أو مقتنياتك، وسنبدأ قراءة الروابط بينها.');const chosen=new Set([...state.lists.favorite,...state.lists.owned]),favNotes=new Set(profile.slice(0,6).map(x=>x[0])),recs=items.filter(p=>!chosen.has(p.id)&&p.imageStatus==='official').map(p=>({p,shared:noteKeysOf(p).filter(k=>favNotes.has(k))})).filter(x=>x.shared.length>1).sort((a,b)=>b.shared.length-a.shared.length).slice(0,8);return intro('تفاصيل صغيرة. بصمةٌ خاصة.','هذه قراءة لاختياراتك، وتتغير مع كل عطر تضيفه إلى المفضلة أو مقتنياتك.','YOUR OLFACTORY SIGNATURE')+`<div class="profile-layout"><section class="profile-panel"><h2>النوتات الأقرب إليك</h2><p>تكرار النوتة بين ${count} عطرًا من اختياراتك، وليس نسبةً في تركيبة العطر.</p>${profile.slice(0,7).map(([key,n])=>`<div class="note-bar"><div class="bar-label"><button data-action="explore-note" data-value="${esc(key)}">${esc(noteInfo(key).ar)}</button><small>${n} من ${count} عطرًا</small></div><div class="bar-track"><span style="width:${Math.round(n/count*100)}%"></span></div></div>`).join('')}</section><section class="profile-panel"><span class="eyebrow">A TASTE, TAKING SHAPE</span><h2>خريطتك في كلمات</h2><p>النوتات المتكررة في خزانَتك تقودك إلى عطور تشترك معها في المكونات المعلنة. التجربة على بشرتك هي الحكم.</p><div class="note-groups">${profile.slice(0,10).map(([key])=>`<button class="chip" data-action="explore-note" data-value="${esc(key)}">${esc(noteInfo(key).ar)}</button>`).join('')}</div><a class="text-button" href="#journal">اقرأ مذكّرتك ${icon('arrow',15)}</a></section></div><div class="section-heading"><div><h2>روابط قد تستحق التجربة</h2><p>اختيارات تشترك في نوتات مع خزانَتك.</p></div></div><div class="perfume-grid">${recs.map(({p,shared})=>card(p,'يجمعك به: '+shared.slice(0,3).map(k=>noteInfo(k).ar).join('، '))).join('')}</div>`;}
function openModal(title,content){returnFocus=document.activeElement;$('#modal').setAttribute('aria-label',title);$('#modal-content').innerHTML=`<div class="modal-header"><b>${esc(title)}</b><button class="icon-button" data-action="close-modal" aria-label="إغلاق">${icon('close',18)}</button></div><div class="modal-main">${content}</div>`;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function closeModal(){currentDetail=null;$('#modal').close();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function detail(p){if(!p){toast('بيانات هذا العطر غير متاحة بعد.');return;}currentDetail=p.id;const stages=[['top','الافتتاحية','TOP NOTES'],['middle','القلب','HEART NOTES'],['base','القاعدة','BASE NOTES'],['key','النوتات الرئيسية','KEY NOTES']],has=allNotes(p).length,review=state.personal[p.id]||{rating:0,note:''};
 const sourceNote=p.notesStatus==='official'?'النوتات كما أعلنتها دار العطر.':p.notesStatus==='custom'?'بيانات أضفتها إلى مكتبتك الشخصية.':p.notesStatus==='legacy'?'من كتالوجك السابق؛ لم تُراجع هذه النوتات في النسخة الجديدة بعد.':'لم تتوفر لدينا نوتات موثقة لهذا العطر بعد.';
 const related=similarTo(p,items,4);
 openModal('ملف العطر',`<div class="detail-layout"><div class="detail-visual">${p.image?image(p,'bottle',true):`<div class="bottle" style="display:grid;place-items:center">${icon('bottle',110)}</div>`}<p class="visual-caption">${p.imageStatus==='official'?'صورة الزجاجة الأصلية من دار العطر':p.imageStatus==='legacy'?'صورة من الكتالوج السابق':p.imageStatus==='custom'?'صورة أضفتها أنت':'الصورة الأصلية غير متوفرة بعد'}</p><div class="detail-tools"><button class="secondary-button" data-action="compare-add" data-id="${p.id}">${icon('compare',14)} ${state.compare.includes(p.id)?'في المقارنة':'قارن العطر'}</button><button class="secondary-button" data-action="new-journal" data-id="${p.id}">${icon('journal',14)} سجّل تجربة</button></div></div><div class="detail-copy"><span class="detail-brand" lang="en">${esc(p.brand)}</span><h2 class="detail-title" lang="en">${esc(p.name)}</h2><div class="detail-meta">${p.concentration?`<span lang="en">${esc(p.concentration)}</span>`:''}${p.year?`<span>${p.year}</span>`:''}${p.perfumer?`<span>${esc(p.perfumer)}</span>`:''}</div><div class="detail-family">${families(p).map(f=>`<button class="family-label" data-action="detail-family" data-value="${f}">${FAMILIES[f]}</button>`).join('')}</div><div class="detail-collections">${Object.entries(LISTS).map(([list,label])=>`<button class="collection-toggle ${isIn(list,p.id)?'active':''}" data-action="toggle-list" data-list="${list}" data-id="${p.id}" aria-pressed="${isIn(list,p.id)}">${icon(({favorite:'heart',owned:'bottle',try:'notes',buy:'plus'})[list],15)}${label}<span class="toggle-check">${icon('check',14)}</span></button>`).join('')}</div><section class="detail-section"><h3>داخل الرائحة</h3><p>${p.notes.key?.length?'النوتات الرئيسية لا تعني ترتيبًا زمنيًا على البشرة.':'رحلة العطر من الانطباع الأول إلى أثره الأخير.'}</p>${has?stages.filter(([key])=>p.notes[key]?.length).map(([key,label,en])=>`<div class="notes-stage"><h4 class="stage-heading">${label}<small>${en}</small></h4><div class="pyramid-notes">${p.notes[key].map(n=>{const info=noteInfo(n);return `<button class="pyramid-note" data-action="explore-note" data-value="${esc(info.key)}">${art(info.family,info.key)}<b>${esc(info.ar)}</b><small lang="en">${esc(n)}</small></button>`;}).join('')}</div></div>`).join(''):`<p class="help-text">نراجع مصدر هذا العطر لإضافة نوتاته. يمكنك توثيق انطباعك في الأسفل.</p>`}<div class="source-box">${icon('check',14)}<span>${sourceNote}${p.sourceUrl?` <a href="${esc(safeURL(p.sourceUrl))}" target="_blank" rel="noopener noreferrer">موقع ${esc(p.source||p.brand)} ${icon('external',10)}</a>`:''}${p.checkedAt?`<br>آخر مراجعة للمصدر: ${dateText(p.checkedAt)}`:''}</span></div></section><section class="detail-section"><h3>رأيك هو الأهم.</h3><p>تقييم وملاحظة لك وحدك، بعيدًا عن ضجيج الآراء.</p><form class="personal-form" id="review-form" data-id="${p.id}"><div><label class="field-label" for="review-rating">تقييمي الشخصي</label><div class="rating-control"><input id="review-rating" name="rating" type="range" min="0" max="10" step="1" value="${review.rating}" aria-label="تقييمي من عشرة"><output id="review-output">${review.rating||'—'}</output><small>/ 10</small></div></div><div class="field"><label for="review-note">ما الذي تشعر به؟</label><textarea name="note" id="review-note" maxlength="1000" placeholder="كيف تطور على بشرتك؟ ما الذي أحببته؟">${esc(review.note)}</textarea><small>خصوصية كاملة: تظهر هذه الملاحظات في مكتبتك فقط.</small></div><div><button class="primary-button" type="submit">${icon('check',15)} حفظ انطباعي</button></div></form></section>${p.id.startsWith('custom-')?`<div class="detail-section"><button class="danger-link" data-action="delete-custom" data-id="${p.id}">حذف هذا العطر المضاف شخصيًا</button></div>`:''}</div></div>${related.length?`<section><div class="section-heading"><div><span class="eyebrow">FOLLOW THE NOTES</span><h2>نوتاتٌ تقودك إلى…</h2><p>عطور تتشارك بعض النوتات المعلنة.</p></div></div><div class="perfume-grid">${related.map(({item,shared})=>card(item,shared.slice(0,2).map(k=>noteInfo(k).ar).join(' · '))).join('')}</div></section>`:''}`);
 currentDetail=p.id;
}
function settings(){currentDetail=null;openModal('مساحتك وإعداداتك',`<div class="narrow-modal">${user?.authMethod==='sites'?'<div class="settings-notice">مساحة التجربة الخاصة: مكتبتها منفصلة عن رابط Scentory السابق. استورد نسخة JSON إذا رغبت في تجربة مقتنياتك هنا.</div>':''}<section class="settings-section"><span class="eyebrow">MAKE IT YOURS</span><h3>أيقونة تليق بشاشة الآيفون.</h3><p>ثبّت Scentory لفتحه مثل تطبيق مستقل.</p><ol><li>افتح رابط التطبيق في Safari.</li><li>اضغط زر المشاركة ${icon('upload',13)}.</li><li>اختر «إضافة إلى الشاشة الرئيسية»، ثم «إضافة».</li></ol>${installPrompt?'<button class="primary-button" data-action="install">تثبيت التطبيق</button>':''}<div class="settings-notice">${matchMedia('(display-mode:standalone)').matches?'التطبيق يعمل الآن بوضع مستقل.':'الأيقونة جاهزة للتثبيت باسم Scentory.'}</div></section><section class="settings-section"><h3>مكتبتك أينما كنت</h3><p>${user?`أنت مسجّل باسم <b>${esc(user.username)}</b>. ${syncPaused?'تحتاج مكتبتك إلى دمج تغييرات الجهازين.':'قوائمك وملاحظاتك وتجاربك تُحفظ في حسابك.'}`:'استخدم حسابًا لمزامنة مقتنياتك وملاحظاتك بين أجهزتك. وحتى ذلك الحين، تُحفظ على هذا الجهاز.'}</p><div class="form-actions"><button class="secondary-button" data-action="account">${icon('cloud',16)} ${user?'إدارة الحساب':'الدخول أو إنشاء حساب'}</button></div></section><section class="settings-section"><h3>نسخة من حكايتك.</h3><p>صدّر خزانَتك وملاحظاتك وتجاربك في ملف واحد، أو ادمج نسخة محفوظة دون حذف بياناتك الحالية.</p><div class="form-actions"><button class="secondary-button" data-action="export">${icon('download',15)} تصدير نسخة</button><button class="secondary-button" data-action="import">${icon('upload',15)} استيراد ودمج</button></div></section><section class="settings-section"><h3>كتالوج يتوسع بمصادره.</h3><div class="settings-grid"><div><span class="stat">${meta.stats?.fragrances||0}</span><p>عطرًا في الكتالوج</p></div><div><span class="stat">${meta.stats?.officialImages||0}</span><p>بصور رسمية عالية الدقة</p></div></div><p>نوتات موثقة من المصدر في ${meta.stats?.officialNotes||0} عطرًا. العطور المحفوظة من النسخة السابقة تحمل توضيحًا عند الحاجة إلى مراجعة بياناتها. العائلات العطرية في التصفية استنتاج من النوتات المعلنة.</p><p>المراجعة: ${dateText(meta.updatedAt||today())}. الإصدار ${VERSION}.</p><button class="text-button" data-action="check-update">التحقق من تحديث التطبيق ${icon('cloud',14)}</button></section></div>`);}
function account(mode='login'){currentDetail=null;if(user){openModal('حسابك ومكتبتك',`<div class="narrow-modal"><span class="eyebrow">YOUR PRIVATE ARCHIVE</span><h2>${esc(user.username)}</h2><p class="live-status">${esc($('#connection').textContent)}</p><p>تُفصل مكتبة كل حساب عن الحسابات الأخرى على هذا الجهاز.</p><div class="form-actions">${syncPaused?'<button class="primary-button" data-action="merge-cloud">دمج تغييرات الجهازين</button>':'<button class="secondary-button" data-action="sync-now">مزامنة الآن</button>'}<button class="secondary-button" data-action="export">نسخة احتياطية</button></div><section class="settings-section"><h3>إضافة مكتبة هذا الجهاز إلى الحساب</h3><p>إذا كانت لديك قوائم محفوظة قبل الدخول، يمكنك دمجها مرة واحدة.</p><button class="text-button" data-action="merge-guest">دمج المكتبة المحلية</button></section><section class="settings-section">${user.authMethod==='sites'?`<a class="danger-button" href="${esc(user.signOutPath)}" target="_top">${icon('logout',15)} تسجيل الخروج</a>`:`<button class="danger-button" data-action="logout">${icon('logout',15)} تسجيل الخروج</button>`}<p>ستظهر المكتبة المحلية فقط بعد الخروج. تبقى مكتبة حسابك في حسابك.</p></section><p id="account-message" role="status" class="help-text"></p></div>`);return;}
 const register=mode==='register';openModal(register?'إنشاء حساب شخصي':'الدخول إلى مكتبتك',`<div class="narrow-modal"><span class="eyebrow">YOUR SCENTS, EVERYWHERE</span><h2>${register?'مكانٌ آمن لخزانَتك.':'مرحبًا بعودتك.'}</h2><p>${register?'احفظ مقتنياتك وملاحظاتك في حسابك الخاص.':'ادخل إلى مكتبتك من أي جهاز.'}</p><form id="auth-form" data-mode="${mode}"><div class="field"><label for="auth-username">اسم المستخدم</label><input id="auth-username" name="username" autocomplete="username" minlength="3" maxlength="40" required spellcheck="false"></div><div class="field"><label for="auth-password">كلمة المرور</label><input id="auth-password" type="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="8" maxlength="128" required></div><label class="check-label" style="margin-top:18px"><input type="checkbox" name="merge"> دمج المكتبة المحفوظة على هذا الجهاز مع حسابي</label><div id="auth-error" role="alert"></div><div class="form-actions"><button type="submit" class="primary-button">${register?'إنشاء الحساب':'دخول'} ${icon('arrow',15)}</button><button type="button" class="text-button" data-action="auth-mode" data-value="${register?'login':'register'}">${register?'لدي حساب بالفعل':'إنشاء حساب جديد'}</button></div></form></div>`);}
function newJournal(id=''){currentDetail=null;const selected=id||state.lists.owned[0]||state.lists.favorite[0]||'';openModal('تجربة عطر جديدة',`<div class="narrow-modal"><span class="eyebrow">A MEMORY IN SCENT</span><h2>ما عطر يومك؟</h2><form id="journal-form"><div class="field"><label for="journal-perfume">العطر</label><select id="journal-perfume" name="perfumeId" required><option value="">اختر العطر…</option>${[...items].sort((a,b)=>a.brand.localeCompare(b.brand)).map(p=>`<option value="${p.id}" ${selected===p.id?'selected':''}>${esc(p.brand)} — ${esc(p.name)}</option>`).join('')}</select></div><div class="form-row"><div class="field"><label for="journal-date">التاريخ</label><input type="date" id="journal-date" name="date" value="${today()}" required></div><div class="field"><label for="journal-occasion">المناسبة</label><select id="journal-occasion" name="occasion"><option value="">بدون تحديد</option>${['يوم عمل','يوم هادئ','مناسبة خاصة','خروج مسائي','تجربة عيّنة','سفر'].map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="form-row"><div class="field"><label for="journal-rating">تقييم التجربة</label><select id="journal-rating" name="rating"><option value="0">لم أحدد بعد</option>${Array.from({length:10},(_,i)=>`<option value="${i+1}">${i+1} / 10</option>`).join('')}</select></div><div class="field"><label for="journal-longevity">الثبات على بشرتي</label><input type="number" id="journal-longevity" name="longevity" min="0" max="24" step="0.5" placeholder="بالساعات (اختياري)"></div></div><div class="field"><label for="journal-sillage">الفوحان كما شعرت به</label><select id="journal-sillage" name="sillage"><option value="">لم أحدد بعد</option><option value="close">قريب من البشرة</option><option value="moderate">متوسط</option><option value="strong">قوي</option></select></div><div class="field"><label for="journal-note">تفاصيل لا أريد نسيانها</label><textarea id="journal-note" name="note" maxlength="500" placeholder="الجو، عدد الرشّات، تطور الرائحة…"></textarea></div><div class="form-actions"><button class="primary-button" type="submit">${icon('check',15)} حفظ التجربة</button></div></form></div>`);}
function addCustom(){currentDetail=null;openModal('إضافة عطر إلى كتالوجك',`<div class="narrow-modal"><span class="eyebrow">YOUR COLLECTION, WITHOUT LIMITS</span><h2>عطرٌ خاص بك.</h2><p>أضف عطرًا غير موجود في الكتالوج. تبقى بياناته وصورته تحت تصنيف «إضافة شخصية».</p><form id="custom-form"><div class="form-row"><div class="field"><label for="custom-name">اسم العطر</label><input id="custom-name" name="name" maxlength="120" required></div><div class="field"><label for="custom-brand">دار العطور</label><input id="custom-brand" name="brand" maxlength="100" required></div></div><div class="form-row"><div class="field"><label for="custom-year">سنة الإصدار (اختياري)</label><input id="custom-year" name="year" type="number" min="1801" max="${new Date().getFullYear()+1}"></div><div class="field"><label for="custom-concentration">التركيز (اختياري)</label><select id="custom-concentration" name="concentration"><option value="">غير محدد</option><option>Eau de Toilette</option><option>Eau de Parfum</option><option>Extrait de Parfum</option><option>Parfum</option><option>Attar</option></select></div></div><div class="field"><label for="custom-image">رابط صورة الزجاجة (اختياري)</label><input id="custom-image" name="image" type="url" dir="ltr" placeholder="https://…"><small>اختر صورة كاملة للزجاجة؛ سيعرضها التطبيق بلا قصّ.</small></div><div class="field"><label for="custom-source">رابط المصدر (اختياري)</label><input id="custom-source" name="sourceUrl" type="url" dir="ltr" placeholder="https://…"></div><div class="field"><label for="custom-notes">النوتات الرئيسية (اختياري)</label><input id="custom-notes" name="notes" placeholder="فانيلا، صندل، هيل…"><small>افصل بين النوتات بفاصلة.</small></div><label class="check-label" style="margin-top:18px"><input type="checkbox" name="owned" checked> أضفه إلى مقتنياتي</label><div id="custom-error" role="alert"></div><div class="form-actions"><button type="submit" class="primary-button">${icon('plus',15)} إضافة إلى مكتَبتي</button></div></form></div>`);}
function confirmAction(title,copy,action,id){openModal(title,`<div class="narrow-modal"><h2>${title}</h2><p>${copy}</p><div class="form-actions"><button class="danger-button" data-action="${action}" data-id="${esc(id)}">تأكيد الحذف</button><button class="secondary-button" data-action="close-modal">إلغاء</button></div></div>`);}
function toggleList(list,id){if(!LISTS[list]||!byId(id))return;const active=isIn(list,id);state.lists[list]=active?state.lists[list].filter(x=>x!==id):[id,...state.lists[list]];save();toast(active?`أُزيل من ${LISTS[list]}`:`أُضيف إلى ${LISTS[list]}`);if(currentDetail)detail(byId(currentDetail));render();}
function compareAdd(id){if(!byId(id))return;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else{if(state.compare.length>=3){toast('اختر حتى ثلاثة عطور في المقارنة.');return;}state.compare.push(id);}save();if(currentDetail)detail(byId(currentDetail));if(page==='compare')render();else $$(`[data-action="compare-add"][data-id="${id}"]`).forEach(b=>{b.classList.toggle('active',state.compare.includes(id));b.setAttribute('aria-pressed',String(state.compare.includes(id)));});}
function browse(){if(page!=='discover'){location.hash='discover';}requestAnimationFrame(()=>$('#catalog-section')?.scrollIntoView({behavior:'smooth'}));}
function exportBackup(){const payload={format:'scentory-backup',version:2,exportedAt:new Date().toISOString(),state:cleanState(state)};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='scentory-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('نسختك جاهزة للحفظ في الملفات.');}
const actions={
 'close-modal':closeModal,'detail':b=>detail(byId(b.dataset.id)),'settings':settings,'account':()=>account(),'add-custom':addCustom,'new-journal':b=>newJournal(b.dataset.id||''),'favorite':b=>toggleList('favorite',b.dataset.id),'toggle-list':b=>toggleList(b.dataset.list,b.dataset.id),'compare-add':b=>compareAdd(b.dataset.id),
 'compare-remove':b=>{state.compare=state.compare.filter(x=>x!==b.dataset.id);save();if(page==='compare')render();},'compare-clear':()=>{state.compare=[];save();if(page==='compare')render();},'browse':browse,
 'family':b=>{filters.family=b.dataset.value;limit=24;$$('.family-row .chip').forEach(x=>{const active=x.dataset.value===filters.family;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active));});updateResults();},
 'preset':b=>{filters.family=b.dataset.value;filters.query='';limit=24;render();browse();},'detail-family':b=>{closeModal();filters.family=b.dataset.value;limit=24;if(page==='discover'){render();browse();}else{location.hash='discover';}},
 'explore-note':b=>{if($('#modal').open)closeModal();filters={query:'',brand:'',family:'',notes:[b.dataset.value],exclude:[],images:false};filterOpen=true;limit=24;if(page==='discover'){render();browse();}else{location.hash='discover';setTimeout(browse,50);}},
 'toggle-filters':()=>{filterOpen=!filterOpen;$('#filters-slot').innerHTML=renderFilters();const b=$('[data-action="toggle-filters"]');b.classList.toggle('active',filterOpen);b.setAttribute('aria-expanded',String(filterOpen));},
 'reset-filters':()=>{filters={query:'',brand:'',family:'',notes:[],exclude:[],images:false};limit=24;render();},'clear-query':()=>{filters.query='';$('#catalog-search').value='';limit=24;updateResults();$('#catalog-search').focus();},
 'remove-note':b=>{filters.notes=filters.notes.filter(n=>n!==b.dataset.value);$('#filters-slot').innerHTML=renderFilters();limit=24;updateResults();},'remove-exclude':b=>{filters.exclude=filters.exclude.filter(n=>n!==b.dataset.value);$('#filters-slot').innerHTML=renderFilters();limit=24;updateResults();},
 'load-more':()=>{limit+=24;updateResults();},'list-tab':b=>{activeList=b.dataset.value;render();},'note-family':b=>{noteFamily=b.dataset.value;noteLimit=60;render();},'more-notes':()=>{noteLimit+=60;render();},
 'export':exportBackup,'import':()=>$('#import-file').click(),'install':async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;}else settings();},'auth-mode':b=>account(b.dataset.value),
 'delete-journal':b=>confirmAction('حذف هذه التجربة؟','ستُحذف الملاحظة من المذكّرة، ويبقى العطر في خزانَتك.','confirm-delete-journal',b.dataset.id),
 'confirm-delete-journal':b=>{state.journal=state.journal.filter(j=>j.id!==b.dataset.id);save();closeModal();render();toast('حُذفت التجربة.');},
 'delete-custom':b=>confirmAction('حذف العطر الشخصي؟','سيُحذف هذا العطر من الكتالوج والقوائم والملاحظات والتجارب المرتبطة به.','confirm-delete-custom',b.dataset.id),
 'confirm-delete-custom':b=>{const id=b.dataset.id;state.custom=state.custom.filter(p=>p.id!==id);for(const k of Object.keys(LISTS))state.lists[k]=state.lists[k].filter(x=>x!==id);delete state.personal[id];state.journal=state.journal.filter(j=>j.perfumeId!==id);state.compare=state.compare.filter(x=>x!==id);save();closeModal();render();toast('حُذف العطر الشخصي.');},
 'sync-now':async()=>{if(!cloudReady){try{const remote=await api('state');cloudRevision=remote.revision;cloudReady=true;if(!dirty){state=cleanState(remote.state);write(stateKey,state);render();}}catch{toast('تعذر الاتصال بالحساب.');return;}}await flushCloud();account();},
 'merge-guest':()=>{const guest=read(GUEST_KEY)||read('scentory-b-v1');state=mergeStates(guest,state);save();render();account();toast('دُمجت المكتبة المحلية مع حسابك.');},
 'merge-cloud':async()=>{try{const remote=await api('state');state=mergeStates(remote.state,state);cloudRevision=remote.revision;syncPaused=false;cloudReady=true;save();await flushCloud();render();account();toast('دُمجت النسختان؛ راجع قوائمك بعد الدمج.');}catch{toast('تعذر الدمج؛ النسخة المحلية محفوظة.');}},
 'logout':async()=>{await flushCloud();if(dirty){toast('تغييراتك لم تصل إلى الحساب بعد. حاول المزامنة أو صدّر نسخة قبل الخروج.');return;}try{await api('auth/logout',{});user=null;stateKey=GUEST_KEY;state=cleanState(read(GUEST_KEY));dirty=false;cloudReady=false;cloudRevision=0;syncPaused=false;closeModal();render();toast('تم الخروج.');}catch{toast('تعذر تسجيل الخروج؛ حاول مجددًا.');}},
 'check-update':async()=>{try{const reg=await navigator.serviceWorker.getRegistration();if(reg){await reg.update();toast(reg.waiting?'تحديث جديد جاهز؛ أعد فتح التطبيق لتفعيله.':'تم فحص التحديثات.');}else toast('أعد تحميل الصفحة للتحقق من أحدث إصدار.');}catch{toast('تعذر فحص التحديثات الآن.');}}
};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const fn=actions[b.dataset.action];if(fn){e.preventDefault();try{await fn(b);}catch(err){console.error('action failed',b.dataset.action,err);toast('لم تكتمل العملية. بياناتك المحفوظة لم تُحذف.');}}});
document.addEventListener('input',e=>{if(e.target.id==='catalog-search'){filters.query=e.target.value;limit=24;updateResults();}if(e.target.id==='review-rating')$('#review-output').textContent=Number(e.target.value)||'—';if(e.target.id==='note-search'){noteQuery=e.target.value;noteLimit=60;const pos=e.target.selectionStart;render();const input=$('#note-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('change',e=>{const id=e.target.id;if(id==='brand-filter')filters.brand=e.target.value;else if(id==='note-filter'){if(e.target.value&&!filters.notes.includes(e.target.value))filters.notes.push(e.target.value);$('#filters-slot').innerHTML=renderFilters();}else if(id==='exclude-filter'){if(e.target.value&&!filters.exclude.includes(e.target.value))filters.exclude.push(e.target.value);$('#filters-slot').innerHTML=renderFilters();}else if(id==='official-filter')filters.images=e.target.checked;else if(id==='sort-select')sort=e.target.value;else return;limit=24;updateResults();});
document.addEventListener('submit',async e=>{if(!['review-form','journal-form','auth-form','custom-form'].includes(e.target.id))return;e.preventDefault();const form=e.target,fd=new FormData(form),data=Object.fromEntries(fd),button=form.querySelector('[type="submit"]');
 if(form.id==='review-form'){state.personal[form.dataset.id]={rating:Number(data.rating)||0,note:data.note.trim().slice(0,1000),updatedAt:Date.now()};save();render();toast('حُفظ انطباعك.');return;}
 if(form.id==='journal-form'){if(!byId(data.perfumeId)){toast('اختر عطرًا من الكتالوج.');return;}state.journal.unshift({id:crypto.randomUUID(),perfumeId:data.perfumeId,date:data.date,occasion:data.occasion,rating:Number(data.rating),longevity:Number(data.longevity)||0,sillage:data.sillage,note:data.note.trim().slice(0,500)});state=cleanState(state);save();closeModal();if(page==='journal')render();else location.hash='journal';toast('حُفظت التجربة في مذكّرتك.');return;}
 if(form.id==='custom-form'){if((data.image&&!safeURL(data.image))||(data.sourceUrl&&!safeURL(data.sourceUrl))){$('#custom-error').innerHTML='<p class="form-error">استخدم رابطًا آمنًا يبدأ بـ https://.</p>';return;}if(state.custom.length>=200){toast('وصلت إلى حد ٢٠٠ عطر شخصي. صدّر نسخة لإدارة كتالوجك.');return;}const p={id:'custom-'+crypto.randomUUID(),name:data.name.trim(),brand:data.brand.trim(),year:data.year,concentration:data.concentration,image:data.image,sourceUrl:data.sourceUrl,notes:{key:data.notes.split(/[,،;]/).map(x=>x.trim()).filter(Boolean)},notesStatus:'custom'};const cleaned=cleanState({...state,custom:[...state.custom,p]}).custom.find(x=>x.id===p.id);if(!cleaned){toast('تحقق من اسم العطر ودار العطور.');return;}state.custom.push(cleaned);if(fd.has('owned'))state.lists.owned.unshift(p.id);save();allItems();closeModal();render();detail(byId(p.id));toast('أُضيف عطرُك إلى الكتالوج.');return;}
 if(form.id==='auth-form'){button.disabled=true;$('#auth-error').innerHTML='';try{const r=await api('auth/'+form.dataset.mode,{username:data.username,password:data.password});closeModal();await connectUser(r.user,{importGuest:fd.has('merge')});toast('مرحبًا بك في مكتبتك.');}catch(err){$('#auth-error').innerHTML=`<p class="form-error">${esc(err.message)}</p>`;}finally{if(button.isConnected)button.disabled=false;}}
});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2000000){toast('ملف النسخة كبير جدًا. الحد المسموح ٢ ميغابايت.');return;}try{const raw=JSON.parse(await file.text());const payload=raw.format==='scentory-backup'?raw.state:raw;if(!payload||!payload.lists||typeof payload.lists!=='object')throw new Error();state=mergeStates(payload,state);save();allItems();if($('#modal').open)closeModal();render();toast('دُمجت النسخة مع خزانَتك دون حذف بياناتك.');}catch{toast('الملف غير صالح. اختر نسخة Scentory بصيغة JSON.');}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>{currentDetail=null;});
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const img=e.target,placeholder=document.createElement('span');placeholder.className='no-photo';placeholder.textContent='S';const small=document.createElement('small');small.textContent='الصورة غير متوفرة';placeholder.append(small);placeholder.setAttribute('role','img');placeholder.setAttribute('aria-label',img.alt+' — الصورة غير متوفرة');img.replaceWith(placeholder);},true);
function route(){const hash=decodeURIComponent(location.hash.slice(1));page=NAV.some(([id])=>id===hash)?hash:'discover';render();if(hash.startsWith('perfume/'))detail(byId(hash.slice(8)));window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('hashchange',route);window.addEventListener('online',()=>{updateStatus();flushCloud();});window.addEventListener('offline',updateStatus);window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});document.addEventListener('visibilitychange',()=>{if(!document.hidden){updateStatus();flushCloud();}});
document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});document.addEventListener('touchmove',e=>{if(e.touches.length>1)e.preventDefault();},{passive:false});
async function boot(){try{const response=await fetch('/catalog.json',{cache:'no-cache'});if(!response.ok)throw new Error();meta=await response.json();if(!Array.isArray(meta.items)||!meta.items.length)throw new Error();allItems();$('#settings-button').innerHTML=icon('settings',18);$('#account-icon').innerHTML=icon('arrow',14);try{const r=await api('auth/me');if(r.user)await connectUser(r.user);}catch{updateStatus();}route();
 if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').then(reg=>{const inform=()=>{if(reg.waiting){const banner=document.createElement('div');banner.className='update-banner';banner.innerHTML='<p>نسخة جديدة من Scentory جاهزة.</p><button class="primary-button" type="button">تحديث التطبيق</button>';banner.querySelector('button').onclick=()=>{write(stateKey,state);reg.waiting.postMessage({type:'ACTIVATE'});};document.body.append(banner);}};inform();reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.installing?.state==='installed'&&navigator.serviceWorker.controller)inform();});});}).catch(()=>{});let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing&&navigator.serviceWorker.controller){refreshing=true;/* first install should not interrupt the current session */if(sessionStorage.getItem('scentory-update-requested'))location.reload();}});document.addEventListener('click',e=>{if(e.target.closest('.update-banner button'))sessionStorage.setItem('scentory-update-requested','1');});}
 }catch(err){$('#content').innerHTML=empty('تعذّر فتح الكتالوج.','تحقق من الاتصال وأعد تحميل الصفحة. بيانات خزانَتك محفوظة على جهازك.',`<button class="primary-button" id="retry-load">إعادة المحاولة</button>`);$('#retry-load').addEventListener('click',boot);}}
boot();
